/*
 * A034428  E.g.f.: 1 - (1-x)*(tan(x) + sec(x)).
 * https://oeis.org/A034428
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, easy, nice
 * Formula:   a(n) = n·E_{n-1} – E_n, where E_k are Euler zigzag numbers (E_0
 *            = 1) generated by the recurrence
 *            ----------------------------------------------------------------
 *            For k ≥ 1: let neg = Σ_{m=1}^{⌊k/2⌋} (-1)^{m+1} · C(k,2m) ·
 *            E_{k-2m} let pos = Σ_{m=1}^{⌊k/2⌋} (-1)^{m} · C(k,2m) · E_{k-2m}
 *            RHS = 0 if...
 * Range:     u8 n <= 7, u16 n <= 10, u32 n <= 15, u64 n <= 24, u128 n <= 39,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

seq_t a(idx_t n)
{
    /* static cache of Euler numbers */
    static seq_t *E = NULL;          /* array of Euler numbers E[0..] */
    static idx_t E_len = 0;          /* number of computed Euler numbers */

    /* allocate/extend cache if necessary */
    if (n + 1 > E_len) {
        /* enlarge array */
        seq_t *tmp = (seq_t *)realloc(E, (n + 1) * sizeof(seq_t));
        if (!tmp) abort();
        E = tmp;

        /* initialize first Euler number */
        if (E_len == 0) {
            E[0] = 1;          /* E_0 = 1 */
            E_len  = 1;
        }

        /* compute Euler numbers from current length up to n */
        for (idx_t k = E_len; k <= n; ++k) {
            seq_t pos = 0;         /* Σ of terms with positive sign */
            seq_t neg = 0;         /* Σ of terms with negative sign */

            /* binomial coefficient C(k,i), i from 0..k, computed incrementally */
            seq_t binom = 1;        /* C(k,0) */
            for (idx_t i = 1; i <= k; ++i) {
                /* C(k,i) = C(k,i-1) * (k-i+1) / i */
                binom = (binom * (seq_t)(k - i + 1)) / (seq_t)i;

                if ((i & 1) == 0) {    /* i even, corresponds to m = i/2 */
                    idx_t j = k - i;    /* index of previous Euler number */
                    seq_t term = binom * E[j];
                    idx_t m = i >> 1;   /* m = i/2 */
                    if ((m & 1) == 0)      /* (-1)^m = +1  (m even) */
                        pos += term;
                    else
                        neg += term;      /* (-1)^m = -1  (m odd)   */
                }
            }

            /* RHS part of recurrence */
            seq_t rhs = 0;
            if ((k & 1) != 0) {            /* k odd */
                idx_t m = (k - 1) >> 1;    /* (k-1)/2 */
                if ((m & 1) == 0)
                    rhs = 1;                 /* (-1)^{(k-1)/2} = +1 */
                else
                    rhs = (seq_t)(-1);        /* (-1)^{(k-1)/2} = -1 */
            }

            /* compute E_k = neg + rhs - pos */
            seq_t rk = rhs;
            if (rhs == (seq_t)(-1))        /* rhs negative */
                rk = neg - 1;
            else if (rhs == (seq_t)1)
                rk = neg + 1;
            else
                rk = neg;

            E[k] = rk - pos;              /* subtract pos part */
        }
        E_len = n + 1;
    }

    /* compute a(n) from Euler numbers */
    if (n == 0 || n == 1)
        return 0;

    seq_t mul = (seq_t)n * E[n - 1];
    seq_t result = mul - E[n];
    return result;
}
